"""Build offline HTML artifacts from the sealed history and authored review."""
import json,datetime,pathlib,html,urllib.parse,collections
ROOT=pathlib.Path(__file__).resolve().parent
G=json.loads((ROOT/'source/git-history.json').read_text());E=json.loads((ROOT/'source/editorial.json').read_text());D=json.loads((ROOT/'source/deck.json').read_text());CS=G['commits'];esc=lambda s:html.escape(str(s),quote=True)
repo='https://github.com/coolwithyou/noten.changupnote'
shaMap={c['sha'][:7]:c for c in CS}
recorded_dates=sorted(set(E['daily'])|{c['date'] for c in CS})
development_start=datetime.date.fromisoformat(recorded_dates[0])
development_end=datetime.date.fromisoformat(recorded_dates[-1])
development_days=(development_end-development_start).days+1
def source(a):
 if a.startswith('https:'):return f'<a href="{esc(a)}" target="_blank" rel="noopener">공식 TDS {"Colors" if "colors" in a else "Typography"}</a>'
 if a in shaMap:return f'<a href="{repo}/commit/{shaMap[a]["sha"]}" target="_blank" rel="noopener"><code>{a}</code></a>'
 if ':' in a:
  ref,path=a.split(':',1);return f'<a href="{repo}/blob/{ref}/{urllib.parse.quote(path)}" target="_blank" rel="noopener">{esc(a)}</a>'
 if a.startswith('source/'):return f'<a href="{esc(a)}">{esc(a)}</a>'
 link=('../../'+a[5:]) if a.startswith('docs/') else '../../../'+a
 return f'<a href="{esc(link)}">{esc(a)}</a>'
