JS='''const slides=[...document.querySelectorAll('.slide')];let pos=0,notes=false;function show(n){pos=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.hidden=i!==pos;s.querySelector('.speaker').hidden=!notes;});document.getElementById('counter').textContent=(pos+1)+' / '+slides.length;history.replaceState(null,'','#'+(pos+1));document.title='창업노트 회고 · '+(pos+1)+' / '+slides.length;document.getElementById('prev').disabled=pos===0;document.getElementById('next').disabled=pos===slides.length-1;}function toggle(){notes=!notes;show(pos);}async function full(){try{if(document.fullscreenElement)await document.exitFullscreen();else await slides[pos].requestFullscreen();}catch(e){document.getElementById('full').textContent='전체 화면 불가';}}document.getElementById('prev').onclick=()=>show(pos-1);document.getElementById('next').onclick=()=>show(pos+1);document.getElementById('notes').onclick=toggle;document.getElementById('full').onclick=full;document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(pos+1);}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(pos-1);}if(e.key==='Home'){e.preventDefault();show(0);}if(e.key==='End'){e.preventDefault();show(slides.length-1);}if(e.key.toLowerCase()==='n')toggle();if(e.key.toLowerCase()==='f')full();if(e.key.toLowerCase()==='p')window.print();});window.addEventListener('hashchange',()=>show((parseInt(location.hash.slice(1))||1)-1));show((parseInt(location.hash.slice(1))||1)-1);'''
